        val sorted = intArrayOf(1, 2, 3, 4, 5)
        assertTrue(sorted.isSortedWith(naturalOrder()))
        assertFalse(sorted.isSortedWith(reverseOrder()))

        val reversed = intArrayOf(5, 4, 3, 2, 1)
        assertTrue(reversed.isSortedWith(reverseOrder()))
